    raw = os.environ.get("LARCH_STEP5_LINT_FIX_MAX_ATTEMPTS", "")
    if not raw:
        return 3
    try:
        value = int(raw)
    except ValueError:
        _err(f"⚠ review-and-fix: invalid LARCH_STEP5_LINT_FIX_MAX_ATTEMPTS={raw}; using 3")
        return 3
